class Base {
  tag() {
    return `base:${this.label}`;
  }
}

class Child extends Base {
  constructor(label) {
    super();
    this.label = label;
  }

  show() {
    return super.tag();
  }
}

const child = new Child("alpha");
const other = { label: "beta", tag() { return "other"; } };

console.log(child.show());
console.log(child.show.call(other));
